package com.sipsmile.app.data

import androidx.annotation.DrawableRes
import com.sipsmile.app.R

/** The cast. Ids match the ids in ui/chars/ArtData.kt (generated by tools/gen_art.py). */
object Roster {
    const val DROP = "water_drop"
    const val BIRD = "bird"
    const val BUTTERFLY = "butterfly"
    const val CLOUD = "cloud"
    const val PLANE = "paper_plane"
    const val BEE = "bee"
    const val MOON = "moon"

    private val waterPool = listOf(DROP, CLOUD, BIRD)
    private val smilePool = listOf(BIRD, BUTTERFLY, CLOUD, PLANE, BEE)

    /** Picks a character for a reminder; never the same one twice in a row. The moon only shows up in the evening/night. */
    fun pick(type: ReminderType, hourOfDay: Int, last: String): String {
        val base = if (type == ReminderType.WATER) waterPool else {
            if (hourOfDay >= 18 || hourOfDay < 5) smilePool + MOON else smilePool
        }
        val options = base.filter { it != last }
        return (if (options.isEmpty()) base else options).random()
    }

    fun displayName(id: String): String = when (id) {
        DROP -> "Dewy the Water-Drop"
        BIRD -> "Pip the Bluebird"
        BUTTERFLY -> "Flutter the Butterfly"
        CLOUD -> "Nimbus the Cloud"
        PLANE -> "Zoom the Paper Plane"
        BEE -> "Barnaby the Bee"
        MOON -> "Lumi the Moon"
        else -> "Your buddy"
    }

    @DrawableRes
    fun widgetImage(id: String, happy: Boolean): Int = when (id) {
        BIRD -> if (happy) R.drawable.char_bird_happy else R.drawable.char_bird
        BUTTERFLY -> if (happy) R.drawable.char_butterfly_happy else R.drawable.char_butterfly
        CLOUD -> if (happy) R.drawable.char_cloud_happy else R.drawable.char_cloud
        PLANE -> if (happy) R.drawable.char_paper_plane_happy else R.drawable.char_paper_plane
        BEE -> if (happy) R.drawable.char_bee_happy else R.drawable.char_bee
        MOON -> if (happy) R.drawable.char_moon_happy else R.drawable.char_moon
        else -> if (happy) R.drawable.char_water_drop_happy else R.drawable.char_water_drop
    }
}
